// BioSection.tsx
type Props = { register: any; errors: any; watch: any };

export function BioSection({ register, errors, watch }: Props) {
  const bio = watch('bio') ?? '';
  return (
    <LabelledField label="Bio" description={`${bio.length}/280`} errorText={errors.bio?.message}>
      <textarea {...register('bio')} style={{ width: 480 }} rows={4} />
    </LabelledField>
  );
}
```

(RhfProvider and LabelledField are just our local names for the form provider and Cloudscape's labelled field wrapper.)

Our order list filter bar is ugly and I've been asked to bring it up to standard. Look at it and tell me what needs to change, with the changes. Scope is just this one file.

```tsx
// OrderFilters.tsx
import { Button, Select } from '@cloudscape-design/components';

export function OrderFilters({ onApply, statuses }: { onApply: (f: any) => void; statuses: string[] }) {
  // status and min are each kept in their own local state hook (default 'all' and '')
  const handle = () => {
    if (min && isNaN(Number(min))) { alert('Minimum must be a number'); return; }
    onApply({ status, min: min ? Number(min) : undefined });
  };
  return (
    <div style={{ display: 'flex', gap: 12, padding: 8 }}>
      <Select
        selectedOption={{ value: status, label: status }}
        options={statuses.map((s) => ({ value: s, label: s }))}
        onChange={({ detail }) => setStatus(detail.selectedOption.value!)}
      />
      <input value={min} placeholder="Min total" onChange={(e) => setMin(e.target.value)} />
      <button onClick={handle}>Apply</button>
    </div>
  );
}
```
